import { Pagination } from "./Pagination";
import type { Meta, StoryObj } from "@storybook/nextjs";
import { useState } from "react";
import { Flex, Text } from "../../atoms";

export default {
  title: "Design System/Molecules/Pagination",
  component: Pagination,
} as Meta<typeof Pagination>;

type Story = StoryObj<typeof Pagination>;

const ITEMS_PER_PAGE = 10;

const PagerState = ({ totalPages }: { totalPages: number }) => {
  const [currentPage, setCurrentPage] = useState(1);
  const mockData = Array.from(
    { length: totalPages * ITEMS_PER_PAGE },
    (_, i) => `Item ${i + 1}`,
  );

  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentItems = mockData.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  return (
    <Flex
      css={{
        flexDirection: "column",
        backgroundColor: "$bg02",
        height: "100vh",
      }}
    >
      <Text variant="h3">Paginated List</Text>
      <ul>
        {currentItems.map((item, index) => (
          <li key={index}>
            <Text>{item}</Text>
          </li>
        ))}
      </ul>
      <Pagination
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={handlePageChange}
      />
    </Flex>
  );
};

const Template: Story = {
  render: (args) => <PagerState {...args} />,
};

export const Default: Story = {
  ...Template,
  args: {
    totalPages: 9,
  },
};

export const OnePage: Story = {
  ...Template,
  args: {
    totalPages: 1,
  },
};

export const TwoPages: Story = {
  ...Template,
  args: {
    totalPages: 2,
  },
};

export const ThreePages: Story = {
  ...Template,
  args: {
    totalPages: 3,
  },
};

export const FourPages: Story = {
  ...Template,
  args: {
    totalPages: 4,
  },
};
